[[nodiscard]] SmithTestValue smith_test_value_i32(int32_t value);

[[nodiscard]] SmithTestValue smith_test_value_i64(int64_t value);

[[nodiscard]] SmithTestValue smith_test_value_isize(ptrdiff_t value);

